class MappingError(ValueError):
    def __init__(self, code, message): super().__init__(message); self.code=code

def require(ok, code, message):
    if not ok: raise MappingError(code,message)

def number(s, default):
    try: n=Decimal(str(s if s not in ('',None) else default))
    except InvalidOperation: raise MappingError('DICTIONARY_INVALID','Invalid decimal')
    require(n.is_finite(),'DICTIONARY_INVALID','Nonfinite decimal');return n

def validate_model(schema, data):
    try:
        from jsonschema import Draft202012Validator, validators
        from jsonschema.exceptions import ValidationError
    except ImportError: raise MappingError('DEPENDENCY_MISSING','Install examples/app-protocol-mapping-v1/requirements.txt in an isolated Python environment')
    def exact_multiple(validator,divisor,instance,schema):
        if type(instance) not in (int,float):return
        value=Decimal(str(instance));step=Decimal(str(divisor))
        if not value.is_finite() or not step.is_finite() or step<=0 or value/step!=(value/step).to_integral_value():yield ValidationError('Value is not an exact multiple of '+str(divisor))
    exact=validators.extend(Draft202012Validator,{'multipleOf':exact_multiple})
    errors=sorted(exact(schema).iter_errors(data), key=lambda e:str(list(e.path)))
    if errors: raise MappingError('MODEL_CONSTRAINT',str(list(errors[0].path))+': '+errors[0].message)

def source_bytes(path):
    return subprocess.check_output(['/bin/cat',str(path)]) if sys.platform=='darwin' else Path(path).read_bytes()

def read_rows(path, columns):
    # Use the project's established stream-read path on the local Mac volume.
    # UTF-8 validation remains strict; bytes are never repaired or reinterpreted.
    raw=source_bytes(path)
    try: text=raw.decode('utf-8-sig',errors='strict')
    except UnicodeError: raise MappingError('CSV_ENCODING','CSV must be valid UTF-8')
    r=csv.DictReader(io.StringIO(text,newline=''));require(r.fieldnames==columns,'CSV_HEADER',str(path)+' columns mismatch');rows=list(r)
    require(all(None not in x and all(v is not None for v in x.values()) for x in rows),'CSV_SHAPE','Invalid CSV row')
    return rows

def path_parts(path):
    parts=path.split('/')
    require(all(re.fullmatch(r'(?:0x)?[0-9a-fA-F]{1,2}',x) for x in parts),'ADDRESS_INVALID','Use logical hexadecimal TLV path')
    out=tuple(int(x,16) for x in parts);require(all(0<=x<=127 for x in out),'ADDRESS_INVALID','Use logical Type without the container flag');require(all(x<124 for x in out),'ADDRESS_RESERVED','Type7C..7E are common security fields; Type7F is the fixed result component');return out

def schema_at(schema, path):
    current=schema
    for token in path.split('.') if path else []:
        m=re.fullmatch(r'([A-Za-z_][A-Za-z0-9_]*)(\[\])?',token)
        require(m is not None,'MODEL_PATH','Invalid model path '+path)
        require(current.get('type')=='object' and m[1] in current.get('properties',{}),'MODEL_PATH','Missing model node '+path)
        current=current['properties'][m[1]]
        if m[2]:
            require(current.get('type')=='array','MODEL_PATH','[] requires an array');current=current['items']
    return current

def role_schema(model, command, role):
    method=model['methods'][command['method']]
    return method['input'] if role=='request' else method['output']

def length_encode(n):
    require(type(n) is int and 0<=n<=16383,'LENGTH_RANGE','Length must be0..16383')
    return bytes([n]) if n<128 else bytes([0x80|(n>>7),n&127])

def length_decode(buf,pos):
    require(pos<len(buf),'LENGTH_TRUNCATED','Missing Length');a=buf[pos];pos+=1
    if a<128:return a,pos
    require(pos<len(buf),'LENGTH_TRUNCATED','Missing second Length byte');b=buf[pos];pos+=1
    require(b<128,'LENGTH_CONTINUATION','Third Length byte is unsupported');n=((a&127)<<7)|b
    require(n>=128,'LENGTH_NONCANONICAL','Two-byte Length requires128..16383');return n,pos

def decimal_value(v):
    require(type(v) in (int,float),'VALUE_TYPE','Numeric value required')
    require(not isinstance(v,float) or math.isfinite(v),'VALUE_TYPE','Finite value required');return Decimal(str(v))

def scalar_encode(node,value):
    t=node['wire_type'];packed=t.endswith('[]');base=t[:-2] if packed else t
    if packed:
        require(isinstance(value,list) and base in NUM,'VALUE_TYPE','Packed array requires fixed-width numeric elements')
        return b''.join(scalar_encode({**node,'wire_type':base},v) for v in value)
    if base in NUM:
        raw=(decimal_value(value)-number(node['offset'],0))/number(node['scale'],1)
        if base[0] in 'ui':require(raw==raw.to_integral_value(),'VALUE_EXACT','Do not round illegal engineering values');raw=int(raw)
        else:raw=float(raw)
        try: out=struct.pack('>'+NUM[base][0],raw)
        except (struct.error,OverflowError):raise MappingError('VALUE_RANGE','Value outside '+base)
        if base[0]=='f':require(math.isfinite(struct.unpack('>'+NUM[base][0],out)[0]),'VALUE_RANGE','Float overflow')
        return out
    if base=='bool':require(type(value) is bool,'VALUE_TYPE','Strict boolean required');return bytes([int(value)])
    if base=='utf8':
        require(isinstance(value,str),'VALUE_TYPE','String required')
        try:out=value.encode('utf-8',errors='strict')
        except UnicodeError:raise MappingError('VALUE_UTF8','Invalid UTF-8 input')
    elif base=='bytes':
        require(isinstance(value,str) and re.fullmatch(r'(?:[0-9a-fA-F]{2})*',value) is not None,'VALUE_TYPE','Bytes must be even-length hexadecimal');out=bytes.fromhex(value)
    else:raise MappingError('WIRE_TYPE','Unsupported wire type '+base)
    if node['max_bytes'] is not None:require(len(out)<=node['max_bytes'],'VALUE_LENGTH','Value exceeds declared byte limit')
    return out

def scalar_decode(node,buf):
    t=node['wire_type'];packed=t.endswith('[]');base=t[:-2] if packed else t
    if packed:
        width=NUM[base][1];require(len(buf)%width==0,'VALUE_WIDTH','Packed array length is not a multiple of element width')
        return [scalar_decode({**node,'wire_type':base},buf[i:i+width]) for i in range(0,len(buf),width)]
    if base in NUM:
        require(len(buf)==NUM[base][1],'VALUE_WIDTH','Wrong fixed-width scalar length');raw=struct.unpack('>'+NUM[base][0],buf)[0]
        require(not isinstance(raw,float) or math.isfinite(raw),'VALUE_RANGE','Nonfinite wire value');v=Decimal(str(raw))*number(node['scale'],1)+number(node['offset'],0)
        return int(v) if v==v.to_integral_value() else float(v)
    if base=='bool':require(buf in (b'\0',b'\1'),'VALUE_TYPE','Invalid wire boolean');return bool(buf[0])
    if base=='bytes':out=buf.hex().upper()
    elif base=='utf8':
        try:out=buf.decode('utf-8',errors='strict')
        except UnicodeError:raise MappingError('VALUE_UTF8','Invalid UTF-8')
    else:raise MappingError('WIRE_TYPE','Unsupported wire type')
    scalar_encode(node,out);return out

def check_groups(node,data):
    for group in node.get('groups',[]):
        count=sum(name in data for name in group['fields'])
        if group['rule']=='at_least_one':require(count>0,'FIELD_GROUP','At least one of '+','.join(group['fields']))
        else:require(count in (0,len(group['fields'])),'FIELD_GROUP','All or none of '+','.join(group['fields']))

def projected_keys(nodes):
    out=[]
    for n in nodes:
        if n['wire_type']=='group':out.extend(projected_keys(n['children']))
        elif n['key'] is not None:out.append(n['key'])
    return out

def encode_nodes(nodes,data,depth=1):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit')
    require(isinstance(data,dict),'VALUE_TYPE','Object expected')
    allowed=set(projected_keys(nodes))
    require(not(set(data)-allowed),'FIELD_NOT_BOUND','Unmapped business input fields')
    out=bytearray()
    for n in nodes:
        if n['wire_type']=='group':
            value={k:v for k,v in data.items() if k in projected_keys(n['children'])}
            if not value and not n['required']:continue
        else:
            if n['key'] not in data:require(not n['required'],'FIELD_REQUIRED','Missing '+str(n['model_path']));continue
            value=data[n['key']]
        if n['wire_type']=='array':
            require(isinstance(value,list),'VALUE_TYPE','Array expected');item=n['children'][0];payload=b''.join(encode_node(item,v,depth+1) for v in value)
        else:payload=encode_content(n,value,depth)
        out.extend(bytes([n['type_id']|(128 if n['wire_type'] in CONTAINERS else 0)])+length_encode(len(payload))+payload)
    return bytes(out)

def encode_content(n,value,depth):
    if n['wire_type'] in {'object','group'}:
        check_groups(n,value);return encode_nodes(n['children'],value,depth+1)
    return scalar_encode(n,value)

def encode_node(n,value,depth):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit');payload=encode_content(n,value,depth)
    return bytes([n['type_id']|(128 if n['wire_type'] in CONTAINERS else 0)])+length_encode(len(payload))+payload

def read_tlvs(buf):
    pos=0
    while pos<len(buf):
        wire=buf[pos];pos+=1;n,pos=length_decode(buf,pos);require(pos+n<=len(buf),'TLV_BOUNDARY','Value exceeds enclosing TLV/PDU')
        yield wire,buf[pos:pos+n];pos+=n

def decode_content(n,payload,depth):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit')
    if n['wire_type']=='array':
        item=n['children'][0];out=[]
        for wire,b in read_tlvs(payload):
            require(wire&127==item['type_id'],'UNKNOWN_TYPE','Unknown array item Type')
            check_flag(item,wire,b);out.append(decode_content(item,b,depth+1))
        return out
    if n['wire_type'] in {'object','group'}:
        value=decode_nodes(n['children'],payload,depth+1);check_groups(n,value);return value
    return scalar_decode(n,payload)

def check_flag(n,wire,payload):
    container=n['wire_type'] in CONTAINERS
    # Existing application grammar permits either flag on an empty extensible container.
    require(bool(wire&128)==container or (container and not payload),'CONTAINER_FLAG','Type container flag mismatch')

def decode_nodes(nodes,buf,depth=1):
    table={n['type_id']:n for n in nodes};out={};seen=set()
    for wire,b in read_tlvs(buf):
        tid=wire&127;require(tid in table,'UNKNOWN_TYPE','Unknown Type in configured scope');require(tid not in seen,'DUPLICATE_TYPE','Duplicate nonrepeated Type');seen.add(tid);n=table[tid];check_flag(n,wire,b);v=decode_content(n,b,depth)
        if n['wire_type']=='group':require(not(set(out)&set(v)),'MODEL_PATH','Wrapper path collision');out.update(v)
        else:out[n['key']]=v
    for n in nodes:require(not n['required'] or n['type_id'] in seen,'FIELD_REQUIRED','Missing '+n['model_path'])
    return out

