        op,role=row['operation'],row['role'];require(op in commands and role in ROLES,'DIRECTION_INVALID','Unknown operation or role');cmd=commands[op];path=path_parts(row['tlv_path']);require(len(path)<=MAX_DEPTH,'NESTING_LIMIT','Mapping too deep');key=(op,role);lookup=trees.setdefault(key,{})
