def check_snapshot(d,identity):
    require(isinstance(d,dict) and d.get('format_version')==FORMAT,'DICTIONARY_VERSION','Missing or unsupported dictionary format')
    try: validate_model(json.loads((Path(__file__).resolve().parents[1]/'supporting/ble-app-protocol-mapping.schema.json').read_text()),d)
    except MappingError as e:
        if e.code=='MODEL_CONSTRAINT':raise MappingError('DICTIONARY_INVALID',str(e))
        raise
