    for k in ['product_id','firmware_version','function_version','dictionary_version','transport_ref']:
        require(k in identity and identity[k]==d.get('identity',{}).get(k),'IDENTITY_MISMATCH','Exact identity mismatch: '+k)
    addresses=set()
    for op,cmd in d['commands'].items():
        require(op==cmd['operation'] and cmd['method'] in d['thing_model']['methods'],'COMMAND_UNKNOWN','Compiled operation/model mismatch')
        require((cmd['sid'],cmd['cid']) not in addresses,'ADDRESS_CONFLICT','Same address has two definitions');addresses.add((cmd['sid'],cmd['cid']))
        require((cmd['result_component']=='R3.common_u32_7f')==('result' in cmd['receive_variants']),'DICTIONARY_INVALID','Result component/variant mismatch')
        require(('incoming' in cmd['layouts'])==('incoming' in cmd['receive_variants']),'DIRECTION_INVALID','Incoming variant/layout mismatch')
        if cmd['interaction']=='one_way':require(not cmd['receive_variants'],'INTERACTION_INVALID','One-way cannot receive replies')
        for role,nodes in cmd['layouts'].items():
